param([Parameter(Mandatory=$true)][string]$RunDirectory,[string]$ExcludedStartupRun)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$target=Join-Path $root 'evidence/mpu4/skill-cash'
if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Incomplete capture'}
$raw=@(Import-Csv "$RunDirectory/ptm-skill-cpu.csv");$rows=@($raw|Where-Object {$_.event -ne 'installed'})
if(@($rows|Where-Object {$_.event -eq 'entry'}).Count -ne 1 -or @($rows|Where-Object {$_.event -eq 'after' -and $_.address -eq '710F'}).Count -ne 20){throw 'Incomplete feature timing window'}
foreach($r in $rows){if($r.event -notin @('entry','write','read','after','handler','callback') -or !$r.seconds -or !$r.attoseconds){throw 'Invalid timing row'}}
[ordered]@{classification='Natural original physical-input campaign at actual C721 dispatch; passive taps attach after2040 simulated seconds. First20 timer3 arms, original CPU/ROM handler and callback observations; no state injection.';bus_qualification='Writes BEFORE access, reads AFTER, selected opcode fetches AFTER prior instruction. Handler/callback opcode-fetch timestamps are one CPU cycle after their instruction boundary. Exact timestamp strings retain attoseconds.';rows=$rows}|ConvertTo-Json -Depth 6|Set-Content "$target/ptm-skill-cpu.json"
$excluded=$null;if($ExcludedStartupRun){$excluded=[ordered]@{source_run=$ExcludedStartupRun;reason='Installing RAM dispatch taps during startup prevented progression. Stopped owned process; no accepted feature evidence.';observer_sha256=(Get-FileHash "$ExcludedStartupRun/ptm-skill-cpu.lua").Hash;csv_sha256=(Get-FileHash "$ExcludedStartupRun/ptm-skill-cpu.csv").Hash}}
[ordered]@{source_run=$RunDirectory;csv_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.csv").Hash;lua_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.lua").Hash;input_lua_sha256=(Get-FileHash "$RunDirectory/input.lua").Hash;replay_actions_sha256=(Get-FileHash "$RunDirectory/replay-actions.csv").Hash;provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);rows=$rows.Count;excluded_startup_attempt=$excluded;source_tag='mame0281';source_commit='2843a3deb81cf93735244044894196ccfbea4d20'}|ConvertTo-Json -Depth 6|Set-Content "$target/ptm-skill-cpu-verification.json"
Write-Output "Curated $($rows.Count) natural Skill Cash PTM/CPU observations"
